/**
 * Cloudflare Workers entry point — Hive Warfare OS / Droppii Training OS.
 *
 * The ~40 Express routes in src/api/* are served through the Express req/res
 * bridge (src/workers/express-adapter.js) rather than rewritten for the
 * Workers runtime. Hono (ADR 004) provides the Workers-native routing layer;
 * this module is the entry point that wires Hono to the Express app.
 *
 * Secrets (wrangler secret put):
 *   JWT_SECRET, PASSWORD_SALT, ALLOWED_ORIGIN, ADMIN_TOKEN
 */

import { Hono } from 'hono';
import { createExpressHandler } from './express-adapter.js';
import { app as expressApp } from '../server.js';

// Hono routes every request to the Express app via the bridge. The bridge
// builds IncomingMessage/ServerResponse pairs, runs the Express handler, and
// returns a Workers Response carrying the captured status, headers, and body.
const honoApp = new Hono();
honoApp.all('*', createExpressHandler((req, res, next) => expressApp(req, res, next), expressApp));

function jsonResponse(body, status = 200, origin = '*') {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      'Content-Type': 'application/json',
      'Access-Control-Allow-Origin': origin || '*',
      'Access-Control-Allow-Methods': 'GET, POST, PUT, DELETE, OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type, Authorization',
      'X-Content-Type-Options': 'nosniff',
      'X-Frame-Options': 'DENY',
    },
  });
}

async function parseBody(req) {
  try {
    const ct = req.headers.get('content-type') || '';
    if (!ct.includes('application/json')) return null;
    const size = parseInt(req.headers.get('content-length') || '0');
    if (size > 102400) return null;
    return await req.json();
  } catch { return null; }
}

